-- Initial schema for the local SQLite database.
--
-- Conventions (see docs/data-model.md for the full rationale):
--   * Primary keys are TEXT UUIDv7 values generated by the application, so that
--     rows created independently on different devices never collide.
--   * Timestamps are TEXT in UTC, formatted as 2006-01-02T15:04:05.000Z.
--     Calendar dates (birthday, due dates, ...) use the same format.
--   * Money is stored as INTEGER cents.
--   * Every syncable table carries updated_at and a nullable deleted_at
--     (tombstone). Rows are never hard-deleted by the application; reads filter
--     on deleted_at IS NULL. The data scope a table belongs to is fixed per table
--     and registered in internal/db/scopes.go (the "-- scope:" comments below
--     mirror that registry).
--   * Uniqueness that only matters for live rows is enforced with partial
--     indexes (WHERE deleted_at IS NULL) so tombstones do not block re-use.

-- +goose Up

-- ── scope: admin ─────────────────────────────────────────────────────────────

CREATE TABLE users (
    id          TEXT NOT NULL PRIMARY KEY,
    email       TEXT NOT NULL,
    password    TEXT NOT NULL,
    app_role    TEXT NOT NULL DEFAULT 'READONLY' CHECK (app_role IN ('ADMIN', 'SECRETARY', 'TREASURER', 'READONLY')),
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
CREATE UNIQUE INDEX users_email_live ON users (email) WHERE deleted_at IS NULL;

-- Append-only: entries are never updated or deleted, so no updated_at/deleted_at.
CREATE TABLE audit_log (
    id          TEXT NOT NULL PRIMARY KEY,
    action      TEXT NOT NULL CHECK (action IN ('CREATE', 'UPDATE', 'DELETE')),
    entity      TEXT NOT NULL,
    entity_id   TEXT NOT NULL,
    user_id     TEXT NOT NULL,
    data        TEXT,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX audit_log_created_at ON audit_log (created_at);

-- ── scope: members.core ──────────────────────────────────────────────────────

CREATE TABLE members (
    id          TEXT NOT NULL PRIMARY KEY,
    number      INTEGER NOT NULL,
    first_name  TEXT NOT NULL,
    last_name   TEXT NOT NULL,
    birthday    TEXT,
    entry_date  TEXT,
    exit_date   TEXT,
    comment     TEXT,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
CREATE UNIQUE INDEX members_number_live ON members (number) WHERE deleted_at IS NULL;
CREATE INDEX members_name ON members (last_name, first_name);

CREATE TABLE roles (
    id          TEXT NOT NULL PRIMARY KEY,
    name        TEXT NOT NULL,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
CREATE UNIQUE INDEX roles_name_live ON roles (name) WHERE deleted_at IS NULL;

CREATE TABLE groups (
    id          TEXT NOT NULL PRIMARY KEY,
    name        TEXT NOT NULL,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
CREATE UNIQUE INDEX groups_name_live ON groups (name) WHERE deleted_at IS NULL;

CREATE TABLE sections (
    id          TEXT NOT NULL PRIMARY KEY,
    name        TEXT NOT NULL,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
);
CREATE UNIQUE INDEX sections_name_live ON sections (name) WHERE deleted_at IS NULL;

-- Membership links. Removing a link tombstones the row; re-adding revives it.
CREATE TABLE member_roles (
    member_id   TEXT NOT NULL REFERENCES members (id),
    role_id     TEXT NOT NULL REFERENCES roles (id),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT,
    PRIMARY KEY (member_id, role_id)
);
CREATE INDEX member_roles_role ON member_roles (role_id);

CREATE TABLE member_groups (
    member_id   TEXT NOT NULL REFERENCES members (id),
    group_id    TEXT NOT NULL REFERENCES groups (id),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT,
    PRIMARY KEY (member_id, group_id)
);
CREATE INDEX member_groups_group ON member_groups (group_id);

CREATE TABLE member_sections (
    member_id   TEXT NOT NULL REFERENCES members (id),
    section_id  TEXT NOT NULL REFERENCES sections (id),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT,
    PRIMARY KEY (member_id, section_id)
);
CREATE INDEX member_sections_section ON member_sections (section_id);

-- Inventory has no scope of its own yet; it is club-wide, non-sensitive data
-- and travels with members.core.
CREATE TABLE inventory_items (
    id              TEXT NOT NULL PRIMARY KEY,
    name            TEXT NOT NULL,
    description     TEXT,
    serial_number   TEXT,
    category        TEXT NOT NULL,
    quantity        INTEGER NOT NULL,
    location        TEXT NOT NULL,
    purchase_date   TEXT,
    purchase_price_cents INTEGER,
    created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at      TEXT
);

CREATE TABLE inventory_loans (
    id           TEXT NOT NULL PRIMARY KEY,
    item_id      TEXT NOT NULL REFERENCES inventory_items (id),
    member_id    TEXT NOT NULL REFERENCES members (id),
    loaned_at    TEXT NOT NULL,
    due_date     TEXT,
    returned_at  TEXT,
    notes        TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at   TEXT
);
CREATE INDEX inventory_loans_item ON inventory_loans (item_id);
CREATE INDEX inventory_loans_member ON inventory_loans (member_id);

-- ── scope: members.contact ───────────────────────────────────────────────────

-- 1:1 with members. A member without contact data has no row.
CREATE TABLE member_contacts (
    member_id     TEXT NOT NULL PRIMARY KEY REFERENCES members (id),
    email         TEXT,
    phone         TEXT,
    phone_mobile  TEXT,
    street        TEXT,
    postal_code   TEXT,
    city          TEXT,
    state         TEXT,
    updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at    TEXT
);
CREATE UNIQUE INDEX member_contacts_email_live ON member_contacts (email)
    WHERE deleted_at IS NULL AND email IS NOT NULL;

-- ── scope: members.bank ──────────────────────────────────────────────────────

-- 1:1 with members. Kept apart so that devices/users without the members.bank
-- scope never receive (or can decrypt) IBANs and SEPA mandates.
CREATE TABLE member_bank_details (
    member_id          TEXT NOT NULL PRIMARY KEY REFERENCES members (id),
    account_holder     TEXT,
    iban               TEXT,
    bic                TEXT,
    bank_name          TEXT,
    sepa_mandate_date  TEXT,
    updated_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at         TEXT
);

-- ── scope: finance ───────────────────────────────────────────────────────────

CREATE TABLE finance_transactions (
    id            TEXT NOT NULL PRIMARY KEY,
    date          TEXT NOT NULL,
    description   TEXT NOT NULL,
    amount_cents  INTEGER NOT NULL,
    type          TEXT NOT NULL CHECK (type IN ('income', 'expense')),
    category      TEXT,
    notes         TEXT,
    created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at    TEXT
);
CREATE INDEX finance_transactions_date ON finance_transactions (date);

CREATE TABLE member_fees (
    id            TEXT NOT NULL PRIMARY KEY,
    member_id     TEXT NOT NULL REFERENCES members (id),
    amount_cents  INTEGER NOT NULL,
    due_date      TEXT NOT NULL,
    paid_date     TEXT,
    description   TEXT,
    year          INTEGER NOT NULL,
    created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at    TEXT
);
CREATE INDEX member_fees_member ON member_fees (member_id);

-- ── local only (never synced) ────────────────────────────────────────────────

-- Per-user UI preferences on this device. user_id is a users.id or
-- the config-file admin's fixed id, hence no foreign key.
CREATE TABLE user_preferences (
    id          TEXT NOT NULL PRIMARY KEY,
    user_id     TEXT NOT NULL,
    key         TEXT NOT NULL,
    value       TEXT NOT NULL,
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (user_id, key)
);

-- Session secrets are bound to this device and must never leave it.
CREATE TABLE refresh_tokens (
    id          TEXT NOT NULL PRIMARY KEY,
    token       TEXT NOT NULL UNIQUE,
    user_id     TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    expires_at  TEXT NOT NULL
);

CREATE TABLE password_reset_tokens (
    id          TEXT NOT NULL PRIMARY KEY,
    token       TEXT NOT NULL UNIQUE,
    user_id     TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    expires_at  TEXT NOT NULL
);

-- +goose Down

DROP TABLE password_reset_tokens;
DROP TABLE refresh_tokens;
DROP TABLE user_preferences;
DROP TABLE member_fees;
DROP TABLE finance_transactions;
DROP TABLE member_bank_details;
DROP TABLE member_contacts;
DROP TABLE inventory_loans;
DROP TABLE inventory_items;
DROP TABLE member_sections;
DROP TABLE member_groups;
DROP TABLE member_roles;
DROP TABLE sections;
DROP TABLE groups;
DROP TABLE roles;
DROP TABLE members;
DROP TABLE audit_log;
DROP TABLE users;
